export const SITE_LOJA_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Big Tricot · Catálogo</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Montserrat:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#f7f4ee; --card:#ffffff; --ink:#24201d; --muted:#8a8073; --line:#e8e2d7;\n    --accent:#ad5033; --accent-soft:#bd6245; --ok:#5d7a4a; --chip:#efe7d8;\n    --shadow:0 1px 2px rgba(60,48,32,.05),0 10px 26px rgba(60,48,32,.06);\n    --radius:14px;\n  }\n  *{box-sizing:border-box}\n  html,body{margin:0}\n  body{background:var(--bg); color:var(--ink); font-family:'Montserrat',system-ui,-apple-system,sans-serif; -webkit-font-smoothing:antialiased; line-height:1.45}\n  .serif{font-family:\"Cormorant Garamond\",Georgia,serif}\n  /* banner full-width, começa no TOPO da página (sem faixa preta em cima) */\n  /* Proporção original 1920×600 (3.2:1): a altura acompanha a largura, sem cortar o topo. */\n  .banner{position:relative; width:100%; aspect-ratio:1920/600; max-height:600px; overflow:hidden; background:#181615}\n  .b-slide{position:absolute; inset:0; opacity:0; transition:opacity .8s ease; display:flex; align-items:center; pointer-events:none}\n  .b-slide.on{opacity:1; pointer-events:auto}\n  .b-link{position:absolute; inset:0; display:flex; align-items:center; text-decoration:none; color:inherit}\n  .b-dots{position:absolute; left:0; right:0; bottom:14px; z-index:5; display:flex; gap:8px; justify-content:center}\n  .b-dot{width:9px; height:9px; padding:0; border:0; border-radius:50%; background:rgba(255,255,255,.45); cursor:pointer; transition:width .2s, background .2s}\n  .b-dot.on{background:#fff; width:22px; border-radius:5px}\n  .b-arrow{position:absolute; top:50%; transform:translateY(-50%); z-index:5; width:40px; height:40px; border-radius:50%; border:0; background:rgba(255,255,255,.18); color:#fff; font-size:24px; line-height:1; cursor:pointer; display:flex; align-items:center; justify-content:center}\n  .b-arrow:hover{background:rgba(255,255,255,.32)}\n  .b-prev{left:14px} .b-next{right:14px}\n  @media(max-width:640px){ .b-arrow{display:none} }\n  @media(prefers-reduced-motion: reduce){ .b-slide{transition:none} }\n  .banner .b-bg{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; object-position:center; z-index:0}\n  .banner .b-shade{position:absolute; inset:0; z-index:1; background:linear-gradient(90deg,rgba(24,22,21,.80) 0%,rgba(24,22,21,.38) 46%,rgba(24,22,21,.08) 100%)}\n  .banner .b-in{position:relative; z-index:2; max-width:1760px; margin:0 auto; width:100%; padding:0 72px; color:#fff}\n  .banner .b-kick{font-size:12px; letter-spacing:.3em; text-transform:uppercase; color:#e7decf; font-weight:500}\n  .banner .b-tit{font-size:48px; font-weight:600; line-height:1.04; letter-spacing:.015em; margin:12px 0 0; max-width:640px}\n  .banner .b-sub{font-size:12px; letter-spacing:.24em; text-transform:uppercase; color:#d8cfc0; margin-top:14px}\n  .banner .b-btn{display:inline-flex; align-items:center; gap:8px; margin-top:22px; background:var(--accent); color:#fff; border:0; border-radius:4px; padding:13px 26px; font-size:12px; letter-spacing:.16em; text-transform:uppercase; font-weight:600; cursor:pointer; text-decoration:none}\n  /* FAIXA PRETA GRAFITE abaixo do banner: busca centralizada + cliente/carrinho à direita */\n  .buscafaixa{background:#181615; padding:16px 24px; position:sticky; top:0; z-index:40}\n  .bf-in{position:relative; max-width:1760px; margin:0 auto; display:flex; align-items:center; justify-content:center; gap:14px; flex-wrap:wrap; min-height:46px}\n  .busca{width:100%; max-width:500px; display:flex; align-items:center; gap:10px; background:#fff; border:1px solid #e8e2d7; border-radius:999px; padding:11px 20px; box-shadow:0 1px 2px rgba(0,0,0,.14)}\n  .busca input{border:0; outline:0; background:transparent; width:100%; font-size:14.5px; color:var(--ink)}\n  .bf-right{position:absolute; right:0; top:50%; transform:translateY(-50%); display:flex; align-items:center; gap:14px}\n  .saud{display:flex; align-items:center; gap:8px; font-size:14px; color:#e9e2d6; white-space:nowrap}\n  .btn-cart{display:flex; align-items:center; gap:7px; border:1px solid var(--accent); background:var(--accent); color:#fff; border-radius:999px; padding:9px 17px; font-weight:600; font-size:13px; cursor:pointer; white-space:nowrap}\n  .btn-cart .n{background:#fff; color:var(--accent); border-radius:999px; min-width:20px; height:20px; display:inline-flex; align-items:center; justify-content:center; font-size:12px; padding:0 5px}\n  .abas{display:none}\n  /* categorias no centro — chips minimalistas (borda fina, fundo neutro, ícone SVG) */\n  /* barra que FIXA os ícones no topo (logo abaixo da busca) ao rolar */\n  .cats-bar{position:sticky; top:var(--cats-top,62px); z-index:30; background:var(--bg); border-bottom:1px solid #ece6db; box-shadow:0 6px 12px -10px rgba(44,39,33,.14)}\n  .cats{display:flex; justify-content:center; flex-wrap:wrap; gap:10px; max-width:960px; margin:0 auto; padding:12px 16px}\n  .cats button{display:inline-flex; align-items:center; gap:9px; padding:9px 17px; background:#fdfbf7; border:1px solid #e5dfd4; border-radius:11px; cursor:pointer; color:#6b6358; font-family:inherit; font-size:13px; font-weight:500; letter-spacing:.02em; line-height:1; transition:border-color .18s ease, color .18s ease, background .18s ease, box-shadow .18s ease}\n  .cats button svg{width:18px; height:18px; fill:none; stroke:#ae5033; stroke-width:1.6; opacity:.82; flex:0 0 auto; transition:opacity .18s ease}\n  .cats button:hover{border-color:#d4c6af; color:#2c2721; background:#fff; box-shadow:0 3px 12px rgba(44,39,33,.05)}\n  .cats button.on{border-color:#ae5033; color:#2c2721; background:#fbf2ec}\n  .cats button.on svg{opacity:1}\n  @media(max-width:560px){ .cats{gap:8px; margin-top:22px} .cats button{padding:8px 13px; font-size:12px; gap:7px} .cats button svg{width:16px; height:16px} }\n  /* botão flutuante do WhatsApp */\n  .wa-float{position:fixed; right:18px; bottom:18px; z-index:900; width:56px; height:56px; border-radius:50%; background:#25d366; box-shadow:0 6px 20px rgba(0,0,0,.28); display:flex; align-items:center; justify-content:center; transition:transform .12s ease}\n  .wa-float:hover{transform:scale(1.07)}\n  .wa-float svg{width:30px; height:30px; fill:#fff}\n  @media(max-width:560px){ .cats button{width:74px} .cats .ci{width:54px; height:54px; font-size:23px} .wa-float{width:52px; height:52px; right:14px; bottom:14px} }\n  main{max-width:1760px; margin:0 auto; padding:18px 24px 70px}\n  .sec{margin-top:30px; scroll-margin-top:96px}\n  .sec h2{font-size:30px; margin:0; text-align:center; font-weight:600; color:var(--ink); display:flex; align-items:center; justify-content:center; gap:20px}\n  .sec h2::before,.sec h2::after{content:\"\"; height:1px; width:60px; background:var(--line)}\n  .sec .sub{text-align:center; color:var(--muted); font-size:12px; letter-spacing:.18em; text-transform:uppercase; margin-top:6px}\n  .grade{display:grid; grid-template-columns:repeat(2,1fr); gap:22px; margin-top:24px}\n  @media(min-width:700px){ .grade{grid-template-columns:repeat(3,1fr)} }\n  @media(min-width:1040px){ .grade{grid-template-columns:repeat(4,1fr)} }\n  @media(max-width:430px){ .grade{grid-template-columns:1fr} }\n  .prod{background:#fff; border:0; border-radius:var(--radius); overflow:hidden; box-shadow:var(--shadow); cursor:pointer; transition:transform .14s ease, box-shadow .14s ease}\n  .prod:hover{transform:translateY(-3px); box-shadow:0 2px 6px rgba(60,48,32,.08),0 18px 40px rgba(60,48,32,.12)}\n  .foto{position:relative; aspect-ratio:1/1; background:#efe7d8; overflow:hidden}\n  .foto img{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; z-index:1}\n  .foto .ph{position:absolute; inset:0; z-index:0; display:flex; align-items:center; justify-content:center; font-family:\"Cormorant Garamond\",serif; font-size:34px; color:#c3b49a; letter-spacing:.06em}\n  .badge{position:absolute; left:12px; top:12px; font-size:11px; font-weight:600; padding:5px 11px; border-radius:999px; background:rgba(255,255,255,.95); color:#4f7a44; display:flex; align-items:center; gap:6px; z-index:2; box-shadow:0 1px 3px rgba(0,0,0,.08)}\n  .badge.off{color:#9c7b4a}\n  .badge .dot{width:7px; height:7px; border-radius:50%; background:currentColor}\n  .prod .info{padding:14px 16px 16px}\n  .prod .nome{font-weight:600; font-size:14px; color:var(--ink); line-height:1.3}\n  .preco{margin-top:7px; font-size:11.5px; color:var(--muted)}\n  .preco b{color:var(--accent); font-size:15px; font-weight:700; margin-left:2px}\n  .vazio{text-align:center; color:var(--muted); padding:60px 16px}\n  @media(max-width:900px){ .bf-right{position:static; transform:none; width:100%; justify-content:center; order:2} .busca{order:1; max-width:none} }\n  @media(max-width:640px){ .buscafaixa{padding:12px 16px} .banner{aspect-ratio:1/1; max-height:none} .banner .b-in{padding:0 20px} .banner .b-tit{font-size:30px} main{padding:14px 16px 60px} .sec{margin-top:24px} .sec h2{font-size:24px; gap:12px} .sec h2::before,.sec h2::after{width:34px} }\n  /* ---- popup \"continuar / escolher outro\" ao adicionar no carrinho ---- */\n  .popconf{position:fixed; inset:0; z-index:80; background:rgba(44,39,33,.55); display:flex; align-items:center; justify-content:center; padding:20px}\n  .popconf-box{background:var(--card); border-radius:16px; max-width:360px; width:100%; padding:24px 22px; text-align:center; box-shadow:0 20px 60px rgba(0,0,0,.3)}\n  .popconf-ic{font-size:34px}\n  .popconf-tit{font-weight:700; font-size:17px; margin-top:6px; color:var(--ink)}\n  .popconf-sub{color:var(--muted); font-size:13px; margin-top:4px}\n  .popconf-acts{display:flex; flex-direction:column; gap:9px; margin-top:16px}\n  .popconf-acts button{border-radius:10px; padding:12px; font-size:14px; font-weight:600; cursor:pointer; font-family:inherit}\n  .popconf-b1{background:var(--accent); color:#fff; border:0}\n  .popconf-b2{background:var(--card); color:var(--ink); border:1px solid var(--line)}\n  .popconf-cart{margin-top:12px; background:none; border:0; color:var(--muted); font-size:12.5px; cursor:pointer; text-decoration:underline; font-family:inherit}\n  /* ---- modal produto (largo, 2 colunas) ---- */\n  .modal{position:fixed; inset:0; z-index:60; background:rgba(44,39,33,.55); display:none}\n  .modal.show{display:block}\n  .sheet{position:absolute; inset:3% 2%; max-width:1500px; margin:0 auto; background:var(--card); border-radius:16px; overflow:hidden; display:flex; flex-direction:column; box-shadow:0 24px 70px rgba(0,0,0,.34)}\n  .sheet .topo{display:flex; justify-content:space-between; align-items:center; padding:12px 18px; border-bottom:1px solid var(--line); flex:0 0 auto}\n  .sheet .topo .lb{font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); font-weight:600}\n  .sheet .fechar{border:0; background:var(--chip); width:34px; height:34px; border-radius:50%; font-size:16px; cursor:pointer; color:var(--ink)}\n  .det{flex:1 1 auto; display:flex; min-height:0}\n  .det .lado-foto{flex:1 1 53%; background:#efe7d8; position:relative; overflow:hidden}\n  .det .lado-foto img{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; z-index:1}\n  .det .lado-foto .ph{position:absolute; inset:0; z-index:0; display:flex; align-items:center; justify-content:center; font-family:\"Cormorant Garamond\",serif; font-size:64px; color:#c3b49a}\n  .det .lado-info{flex:1 1 47%; overflow:auto; padding:0 28px 26px}\n  .det .linhalb{text-align:center; font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); font-weight:600; margin-top:24px; margin-bottom:3px}\n  .det .nome{font-size:28px; margin:0 0 14px; font-weight:600; text-align:center; letter-spacing:.01em; line-height:1.1}\n  .vid{width:100%; border-radius:12px; background:#000; margin-bottom:12px; max-height:300px}\n  .comp{text-align:center; color:var(--muted); font-size:13px; letter-spacing:.04em}\n  .prazo{display:flex; gap:8px; align-items:center; background:#f6efe3; border:1px solid var(--line); border-radius:12px; padding:10px 14px; font-size:13px; color:var(--ink); margin:14px 0}\n  .bloco{margin-top:14px}\n  .bloco h5{margin:0 0 5px; font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted)}\n  .bloco ul{margin:0; padding-left:18px; font-size:14px}\n  .bloco li{margin:2px 0}\n  .montar{margin-top:22px; border-top:1px solid var(--line); padding-top:18px}\n  .montar h4{display:flex; align-items:center; gap:8px; font-size:17px; margin:0 0 14px}\n  .lbl{font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); font-weight:600; margin:16px 0 8px}\n  .lbl b{color:var(--ink); text-transform:none; letter-spacing:0; font-weight:600}\n  .lbl .cnt{color:#7a7068; font-weight:400; text-transform:none; letter-spacing:0; font-size:12px}\n  .cores{display:flex; flex-wrap:wrap; gap:11px; align-items:center}\n  /* trava a escolha de cor no topo enquanto os tamanhos rolam */\n  .cor-sticky{position:sticky; top:0; z-index:8; background:var(--card); padding:14px 0 10px; box-shadow:0 10px 10px -10px rgba(0,0,0,.14)}\n  .sw-dot{position:relative; width:36px; height:36px; border-radius:50%; padding:0; outline:0; cursor:pointer; background:#efe7d8 center/cover no-repeat; border:2px solid #fff; box-shadow:0 0 0 1px var(--line); transition:transform .1s ease, box-shadow .1s ease}\n  .sw-dot:hover{transform:scale(1.09); box-shadow:0 0 0 1px #cabfa9}\n  .sw-dot.on{border-color:#fff; box-shadow:0 0 0 2px #ae5033}\n  .sw-dot.has{box-shadow:0 0 0 2px #ae5033}\n  .sw-n{position:absolute; top:-6px; right:-6px; min-width:17px; height:17px; padding:0 4px; border-radius:9px; background:#ae5033; color:#fff; font-size:10px; font-weight:700; line-height:17px; text-align:center; box-shadow:0 0 0 1.5px #fff; pointer-events:none}\n  .corfoto{margin-top:10px; display:flex; flex-direction:row; align-items:center; gap:12px}\n  .corfoto .cf-img{width:75px; height:75px; border-radius:10px; background:#efe7d8; object-fit:cover; border:1px solid var(--line); flex:0 0 auto}\n  .corfoto img.cf-img{cursor:zoom-in}\n  .corfoto .cf-nm{font-weight:600; font-size:14px; color:var(--ink)}\n  .corfoto .cf-amp{font-size:11.5px; color:var(--muted); margin-top:2px}\n  /* ---- lightbox: foto da cor ampliada ---- */\n  .lightbox{position:fixed; inset:0; z-index:90; background:rgba(20,16,12,.9); display:flex; align-items:center; justify-content:center; padding:24px; cursor:zoom-out}\n  .lightbox img{max-width:min(94vw,1100px); max-height:92vh; border-radius:12px; box-shadow:0 20px 70px rgba(0,0,0,.5)}\n  .lightbox .cap{position:fixed; left:0; right:0; bottom:20px; text-align:center; color:#fff; font-size:15px; font-weight:600; text-shadow:0 1px 4px rgba(0,0,0,.6)}\n  .lb-x{position:fixed; top:16px; right:20px; background:rgba(255,255,255,.16); color:#fff; border:0; border-radius:50%; width:42px; height:42px; font-size:18px; cursor:pointer}\n  .grp{margin-top:16px}\n  .grp{margin-bottom:4px}\n  .grp .t{color:var(--accent); font-weight:600; font-size:15px; margin:14px 0 2px; letter-spacing:.01em}\n  .grp:first-child .t{margin-top:4px}\n  .tamrow{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:11px 0; border-bottom:1px solid var(--line)}\n  .tamrow .medbox{flex:1 1 auto; min-width:0}\n  .tamrow .med{font-size:15px; color:var(--ink); font-weight:500; line-height:1.3}\n  .tamrow .med small{color:var(--muted); margin-left:6px}\n  .tamrow .estx{font-size:12.5px; color:#6f685e; margin-top:3px}\n  .tamrow .estx.low{color:var(--accent); font-weight:600}\n  .tamrow .estx.off{color:#9aa0ab}\n  .tamrow .pr{flex:0 0 auto; min-width:92px; text-align:right; color:var(--ink); font-weight:600; font-size:14px; font-family:'Montserrat',sans-serif; margin-left:auto; margin-right:10px; white-space:nowrap; line-height:1.3}\n  .tamrow .stepper{flex:0 0 auto}\n  .stepper{display:flex; align-items:center; gap:0; border:1px solid var(--line); border-radius:999px; overflow:hidden}\n  .stepper button{border:0; background:var(--chip); width:30px; height:30px; font-size:17px; cursor:pointer; color:var(--ink)}\n  .stepper input{width:40px; border:0; text-align:center; font-size:14px; background:transparent; outline:0; -moz-appearance:textfield}\n  .stepper input::-webkit-outer-spin-button,.stepper input::-webkit-inner-spin-button{-webkit-appearance:none}\n  .resumo{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:16px; padding:12px 16px; background:#faf6ef; border:1px solid var(--line); border-radius:10px}\n  .resumo .rz-q{font-size:13.5px; color:var(--muted)}\n  .resumo .rz-v{font-size:19px; font-weight:700; color:var(--ink); font-family:'Montserrat',sans-serif}\n  .addcart{position:sticky; bottom:0; margin-top:10px; width:100%; min-height:46px; border:0; background:#ae5033; color:#fff; border-radius:10px; padding:12px 15px; font-size:15px; font-weight:600; letter-spacing:.01em; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:8px}\n  .addcart:disabled{background:#cdbfa8; cursor:default}\n  @media(max-width:860px){ .det{flex-direction:column; overflow:auto} .det .lado-foto{flex:0 0 auto; aspect-ratio:4/3} .det .lado-info{overflow:visible} .sheet{inset:0; border-radius:0; max-width:none} }\n  /* CELULAR: cada tamanho em 2 linhas — descrição (quebra) em cima; preço à esquerda e\n     o controle de quantidade à direita embaixo. Botões 44×44, o controle nunca encolhe. */\n  @media(max-width:560px){\n    .det .lado-info{padding:0 16px 24px}\n    .tamrow{flex-wrap:wrap; align-items:center; column-gap:10px; row-gap:6px}\n    .tamrow .medbox{flex:1 1 100%; min-width:0}\n    .tamrow .med{min-width:0; word-break:break-word}\n    .tamrow .pr{margin-left:0; margin-right:auto; font-size:15px}\n    .tamrow .stepper{flex:0 0 auto}\n    .stepper button{width:44px; height:44px; font-size:20px}\n    .stepper input{width:48px; height:44px; font-size:16px}\n  }\n  /* ---- carrinho (gaveta) ---- */\n  .cart{position:fixed; inset:0; z-index:70; background:rgba(44,39,33,.5); display:none}\n  .cart.show{display:block}\n  .cart .pane{position:absolute; top:0; right:0; bottom:0; width:100%; max-width:680px; background:var(--bg); display:flex; flex-direction:column; box-shadow:-10px 0 40px rgba(0,0,0,.2)}\n  .cart .ctopo{display:flex; justify-content:space-between; align-items:center; padding:18px 22px; border-bottom:1px solid var(--line); background:var(--card)}\n  .cart .ctopo h3{margin:0; font-size:22px}\n  .cart .itens{flex:1 1 auto; overflow:auto; padding:12px 20px}\n  .citem{display:flex; gap:12px; background:var(--card); border:1px solid var(--line); border-radius:12px; padding:13px 15px; margin-bottom:11px}\n  .citem .d{flex:1}\n  .citem .nm{font-weight:600; font-size:16px}\n  .citem .meta{color:var(--muted); font-size:13.5px; margin-top:2px}\n  .citem .l2{display:flex; align-items:center; justify-content:space-between; margin-top:9px}\n  .citem .sub{color:var(--ink); font-weight:600; font-family:'Montserrat',sans-serif; font-size:15px}\n  .citem .rm{border:0; background:transparent; color:var(--muted); cursor:pointer; font-size:13px; text-decoration:underline}\n  .cfoot{border-top:1px solid var(--line); background:var(--card); padding:18px 22px}\n  .cfoot .tot{display:flex; justify-content:space-between; font-size:18px; margin-bottom:12px}\n  .cfoot .tot b{font-family:'Montserrat',sans-serif; color:var(--ink); font-size:22px; font-weight:700}\n  .cfoot .fin{width:100%; border:0; background:var(--accent); color:#fff; border-radius:12px; padding:17px; font-size:18px; font-weight:600; cursor:pointer}\n  .cvazio{text-align:center; color:var(--muted); padding:50px 16px}\n  footer{text-align:center; color:var(--muted); font-size:12px; padding:30px 16px 50px; border-top:1px solid var(--line)}\n  footer .nm{font-family:\"Cormorant Garamond\",serif; font-size:16px; color:var(--ink)}\n  footer .obs{font-size:11px; margin-top:8px; opacity:.85}\n</style>\n</head>\n<body>\n<section class=\"banner\" id=\"banner\"></section>\n\n<div class=\"buscafaixa\">\n  <div class=\"bf-in\">\n    <label class=\"busca\">🔎<input id=\"q\" placeholder=\"Buscar produto, cor ou referência…\" autocomplete=\"off\"></label>\n    <div class=\"bf-right\">\n      <span id=\"saudacao\" class=\"saud\" style=\"display:none\"></span>\n      <button class=\"btn-cart\" id=\"abrirCart\">🛒 Carrinho <span class=\"n\" id=\"cartN\">0</span></button>\n    </div>\n  </div>\n</div>\n<nav class=\"abas\" id=\"abas\"></nav>\n\n<div class=\"cats-bar\" id=\"catsBar\" style=\"display:none\"><div class=\"cats\" id=\"cats\"></div></div>\n\n<main id=\"app\"><div class=\"vazio\">Carregando catálogo…</div></main>\n\n<a id=\"waFloat\" class=\"wa-float\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"display:none\" aria-label=\"Falar no WhatsApp\" title=\"Falar no WhatsApp\">\n  <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M.057 24l1.687-6.163a11.867 11.867 0 01-1.587-5.945C.16 5.335 5.495 0 12.05 0a11.817 11.817 0 018.413 3.488 11.824 11.824 0 013.48 8.414c-.003 6.557-5.338 11.892-11.893 11.892a11.9 11.9 0 01-5.688-1.448L.057 24zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884a9.82 9.82 0 001.517 5.248l-.999 3.648 3.971-1.015zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.149-.669.149-.198.297-.768.967-.941 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.52.149-.174.198-.298.297-.496.099-.198.05-.372-.025-.521-.074-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51l-.57-.01c-.198 0-.52.074-.792.372s-1.04 1.016-1.04 2.479 1.065 2.876 1.213 3.074c.149.198 2.095 3.2 5.076 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.695.248-1.29.173-1.414z\"/></svg>\n</a>\n\n<footer>\n  <div class=\"nm\">Big Tricot</div>\n  Monte Sião · MG<br>\n  <span id=\"rodape\"></span>\n  <div class=\"obs\">Preços e estoque do Syntech. Fotos e descrições do catálogo Big Tricot.</div>\n</footer>\n\n<div class=\"modal\" id=\"modal\"><div class=\"sheet\" id=\"sheet\"></div></div>\n<div class=\"cart\" id=\"cart\"><div class=\"pane\" id=\"cartPane\"></div></div>\n\n<div id=\"entrada\" style=\"position:fixed;inset:0;z-index:999;background:rgba(44,39,33,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:18px\">\n  <div style=\"background:#fff;border-radius:18px;max-width:420px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.25);overflow:hidden\">\n    <div style=\"padding:26px 24px 8px;text-align:center\">\n      <div style=\"font-family:'Cormorant Garamond',Georgia,serif;font-size:26px;font-weight:700;letter-spacing:.02em;color:#2c2721\">BIG TRICOT</div>\n      <div style=\"font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#ad5033;margin-top:2px\">Catálogo de atacado</div>\n    </div>\n    <div style=\"padding:14px 24px 24px\">\n      <label style=\"display:block;font-size:14px;color:#5f584e;margin-bottom:6px\">Informe o CNPJ da sua loja para entrar</label>\n      <input id=\"entCnpj\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"00.000.000/0000-00\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px\">\n      <div id=\"entMsg\" style=\"font-size:13px;min-height:1px;margin:8px 0;line-height:1.35\"></div>\n      <button id=\"entBtn\" style=\"width:100%;padding:14px;border:0;border-radius:12px;background:#ad5033;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Entrar</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  \"use strict\";\n  var D = (window.__DADOS__ && typeof window.__DADOS__===\"object\") ? window.__DADOS__ : {produtos:[],banco_cores:[],banco_tamanhos:[],estoque:{itens:{}}};\n  var PRODUTOS = Array.isArray(D.produtos)?D.produtos:[];\n  var CORES = {}; (D.banco_cores||[]).forEach(function(c){CORES[c.id]=c;});\n  var TAM = {}; (D.banco_tamanhos||[]).forEach(function(t){TAM[t.id]=t;});\n  var EST = (D.estoque&&D.estoque.itens)?D.estoque.itens:{};\n  var regiao = \"sul\";\n  var filtroTxt = \"\";\n  var sel = { prod:null, corId:null, qtd:{} }; // qtd[\"corId|cod|idtam\"] = n\n  var CART = carregarCart();\n\n  var SECOES = [\n    {key:\"pe\",     titulo:\"Pronta Entrega\", sub:\"Disponível para envio imediato\", test:function(p){return p.pronta_entrega===true;}},\n    {key:\"polisoft\",titulo:\"Linha Polisoft\", sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"polisoft\";}},\n    {key:\"soft\",   titulo:\"Linha Soft\",     sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"soft\";}},\n    {key:\"natal\",  titulo:\"Natal\",          sub:\"Coleção de Natal\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"natal\";}},\n    {key:\"el\",     titulo:\"Edição Limitada\",sub:\"Peças exclusivas, em quantidade reduzida\", promo:true, test:function(p){return p._edicao_limitada===true;}},\n    {key:\"outros\", titulo:\"Outros\",         sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&[\"polisoft\",\"soft\",\"natal\"].indexOf(p.linha)<0;}}\n  ];\n\n  function brl(v){ v=Number(v)||0; return \"R$ \"+v.toFixed(2).replace(\".\",\",\"); }\n  function precoLinha(l){ return Number(regiao===\"norte\"? l.norte : l.sul)||0; }\n  function menorPreco(p){ var m=Infinity; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){var v=precoLinha(l); if(v>0&&v<m)m=v;});}); return m===Infinity?0:m; }\n  function estoqueProduto(p){ var tot=Number(p.estoque_geral)||0; return tot; }\n  function inicial(nome){ return (String(nome||\"?\").trim()[0]||\"?\").toUpperCase(); }\n  function esc(s){ return String(s==null?\"\":s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\"); }\n  function findProd(id){ return PRODUTOS.filter(function(x){return String(x.id)===String(id);})[0]; }\n  function medidaDe(idt){ var t=TAM[idt]; return (t&&(t.medida||t.nome))||idt||\"-\"; }\n\n  // ---------- GRID ----------\n  function badgeHTML(p){ var est=estoqueProduto(p); return est>0?'<span class=\"badge\"><span class=\"dot\"></span>Em estoque</span>':'<span class=\"badge off\"><span class=\"dot\"></span>Sob encomenda</span>'; }\n  function cardProd(p){\n    var mp=menorPreco(p);\n    return '<article class=\"prod\" data-id=\"'+esc(p.id)+'\">'+\n      '<div class=\"foto\">'+ (p.foto? '<div class=\"ph\">'+inicial(p.nome)+'</div><img loading=\"lazy\" src=\"'+esc(p.foto)+'\" onload=\"this.style.opacity=1\" onerror=\"this.remove()\" style=\"opacity:0;transition:opacity .3s\">' : '<div class=\"ph\">'+inicial(p.nome)+'</div>') +\n        badgeHTML(p) +\n      '</div><div class=\"info\"><div class=\"nome\">'+esc(p.nome)+'</div>'+\n      (mp? '<div class=\"preco\">a partir de <b>'+brl(mp)+'</b></div>' : '<div class=\"preco\">—</div>')+\n      '</div></article>';\n  }\n  // Ícones SVG (traço fino, estilo Lucide) por categoria — minimalistas e elegantes.\n  var CAT_SVG={\n    pe:'<path d=\"M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z\"/><path d=\"m3.3 7 8.7 5 8.7-5\"/><path d=\"M12 22V12\"/>',\n    polisoft:'<path d=\"M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83Z\"/><path d=\"m22 17.65-9.17 4.16a2 2 0 0 1-1.66 0L2 17.65\"/><path d=\"m22 12.65-9.17 4.16a2 2 0 0 1-1.66 0L2 12.65\"/>',\n    soft:'<path d=\"M20.24 12.24a6 6 0 0 0-8.49-8.49L5 10.5V19h8.5z\"/><line x1=\"16\" x2=\"2\" y1=\"8\" y2=\"22\"/><line x1=\"17.5\" x2=\"9\" y1=\"15\" y2=\"15\"/>',\n    natal:'<path d=\"m17 14 3 3.3a1 1 0 0 1-.7 1.7H4.7a1 1 0 0 1-.7-1.7L7 14h-.3a1 1 0 0 1-.7-1.7L9 9h-.2A1 1 0 0 1 8 7.3L12 3l4 4.3a1 1 0 0 1-.8 1.7H15l3 3.3a1 1 0 0 1-.7 1.7H17Z\"/><path d=\"M12 22v-3\"/>',\n    el:'<path d=\"M11.5 2.3a.56.56 0 0 1 1 0l2.35 4.76 5.26.77a.56.56 0 0 1 .3.95l-3.8 3.7.9 5.24a.56.56 0 0 1-.82.59L12 15.8l-4.7 2.3a.56.56 0 0 1-.82-.59l.9-5.24-3.8-3.7a.56.56 0 0 1 .3-.95l5.26-.77Z\"/>',\n    outros:'<rect width=\"7\" height=\"7\" x=\"3\" y=\"3\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"14\" y=\"3\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"14\" y=\"14\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"3\" y=\"14\" rx=\"1.5\"/>'\n  };\n  function catSvg(k){ return '<svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">'+(CAT_SVG[k]||CAT_SVG.outros)+'</svg>'; }\n  function render(){\n    var app=document.getElementById(\"app\"), abas=document.getElementById(\"abas\"), cats=document.getElementById(\"cats\"), catsBar=document.getElementById(\"catsBar\");\n    var q=filtroTxt.toLowerCase();\n    var lista=PRODUTOS.filter(function(p){ return !q || String(p.nome||\"\").toLowerCase().indexOf(q)>=0; });\n    var html=\"\", tabs=\"\", chips=\"\", nsec=0;\n    SECOES.forEach(function(s){\n      var ps=lista.filter(s.test); if(!ps.length) return;\n      nsec++;\n      tabs+='<a data-sec=\"sec-'+s.key+'\"'+(s.promo?' class=\"promo\"':'')+'>'+esc(s.titulo)+'</a>';\n      chips+='<button type=\"button\" data-sec=\"sec-'+s.key+'\">'+catSvg(s.key)+'<span>'+esc(s.titulo)+'</span></button>';\n      html+='<section class=\"sec\" id=\"sec-'+s.key+'\"><h2 class=\"serif\">'+esc(s.titulo)+'</h2>'+(s.sub?'<div class=\"sub\">'+esc(s.sub)+'</div>':'')+'<div class=\"grade\">'+ps.map(cardProd).join(\"\")+'</div></section>';\n    });\n    abas.innerHTML=tabs; if(cats) cats.innerHTML=chips; app.innerHTML=html||'<div class=\"vazio\">Nenhum produto encontrado.</div>';\n    if(catsBar) catsBar.style.display = nsec>0 ? \"block\" : \"none\";\n    medirCatsTop(); ligarCatsAtivo();\n  }\n  // mede a altura da faixa de busca pra fixar os ícones logo abaixo dela\n  function medirCatsTop(){ try{ var b=document.querySelector(\".buscafaixa\"); if(b) document.documentElement.style.setProperty(\"--cats-top\", b.offsetHeight+\"px\"); }catch(e){} }\n  // destaca o chip da seção que está em vista (rolagem)\n  var catObs=null;\n  function ligarCatsAtivo(){\n    try{\n      if(catObs){ catObs.disconnect(); catObs=null; }\n      var cats=document.getElementById(\"cats\"); if(!cats || !(\"IntersectionObserver\" in window)) return;\n      var btns={}; cats.querySelectorAll(\"button[data-sec]\").forEach(function(b){ btns[b.getAttribute(\"data-sec\")]=b; });\n      var secs=document.querySelectorAll(\"#app section.sec\"); if(!secs.length) return;\n      catObs=new IntersectionObserver(function(entries){\n        entries.forEach(function(en){ if(en.isIntersecting){ Object.keys(btns).forEach(function(k){ btns[k].classList.toggle(\"on\", k===en.target.id); }); } });\n      },{rootMargin:\"-45% 0px -50% 0px\",threshold:0});\n      secs.forEach(function(s){ catObs.observe(s); });\n    }catch(e){}\n  }\n  window.addEventListener(\"resize\", medirCatsTop);\n  // WhatsApp flutuante (número vem do D.whatsapp; sem número, esconde o botão)\n  function ligarWhatsApp(){\n    var el=document.getElementById(\"waFloat\"); if(!el) return;\n    var wa=String(D.whatsapp||\"\").replace(/\\D/g,\"\"); if(wa && wa.length<=11) wa=\"55\"+wa;\n    if(!wa){ el.style.display=\"none\"; return; }\n    el.href=\"https://wa.me/\"+wa+\"?text=\"+encodeURIComponent(\"Olá! Vim pelo catálogo da Big Tricot 😊\");\n    el.style.display=\"flex\";\n  }\n\n  // ---------- BANNER / CARROSSEL ----------\n  // Lê D.banners (lista, só os ativos). 0 → estado padrão elegante (sem foto fictícia).\n  // 1 → mostra fixo (sem setas/bolinhas/troca). 2+ → carrossel com fade, bolinhas,\n  // setas (desktop), swipe (celular), autoplay (pausa ao interagir) e respeita movimento reduzido.\n  function bannerSlide(b,i){\n    var imgTag=\"\";\n    if(b.img||b.img_mobile){\n      imgTag='<picture>'+\n        (b.img_mobile?'<source media=\"(max-width:640px)\" srcset=\"'+esc(b.img_mobile)+'\">':'')+\n        '<img class=\"b-bg\" '+(i===0?'':'loading=\"lazy\" ')+'src=\"'+esc(b.img||b.img_mobile)+'\" alt=\"\" onerror=\"this.remove()\">'+\n      '</picture>';\n    }\n    var conteudo=imgTag+'<div class=\"b-shade\"></div><div class=\"b-in\">'+\n      (b.kicker?'<div class=\"b-kick\">'+esc(b.kicker)+'</div>':'')+\n      (b.titulo?'<div class=\"b-tit serif\">'+esc(b.titulo)+'</div>':'')+\n      (b.sub?'<div class=\"b-sub\">'+esc(b.sub)+'</div>':'')+\n      (b.botao_texto?'<a class=\"b-btn\" href=\"'+esc(b.botao_link||'#')+'\"'+(b.botao_link?' target=\"_blank\" rel=\"noopener\"':'')+'>'+esc(b.botao_texto)+' ›</a>':'')+\n    '</div>';\n    // Banner inteiro clicável: produto do catálogo tem PRIORIDADE (abre a janela do produto);\n    // senão, link externo. Nunca cria botão por cima da imagem.\n    var pid=(b.produto_id!=null? String(b.produto_id):\"\").replace(/[^\\w\\-.]/g,\"\");\n    if(pid){\n      conteudo='<div class=\"b-link\" style=\"cursor:pointer\" onclick=\"__abrirProd(\\''+pid+'\\')\">'+conteudo+'</div>';\n    } else if(b.botao_link && !b.botao_texto){\n      conteudo='<a class=\"b-link\" href=\"'+esc(b.botao_link)+'\" target=\"_blank\" rel=\"noopener\">'+conteudo+'</a>';\n    }\n    return '<div class=\"b-slide'+(i===0?' on':'')+'\">'+conteudo+'</div>';\n  }\n  function renderBanner(){\n    var el=document.getElementById(\"banner\"); if(!el) return;\n    var bs = Array.isArray(D.banners)? D.banners.filter(function(b){return b && b.ativo!==false;}) : [];\n    if(!bs.length){\n      el.innerHTML='<div class=\"b-slide on\"><div class=\"b-shade\"></div><div class=\"b-in\">'+\n        '<div class=\"b-kick\">Big Tricot · Home Decor</div>'+\n        '<div class=\"b-tit serif\">Tricô que transforma ambientes</div>'+\n        '<div class=\"b-sub\">Qualidade · Design · Pronta entrega</div>'+\n      '</div></div>';\n      return;\n    }\n    var slides=bs.map(bannerSlide).join(\"\");\n    if(bs.length===1){ el.innerHTML=slides; return; } // 1 só: fixo, sem controles\n    var dots='<div class=\"b-dots\">'+bs.map(function(_,i){return '<button class=\"b-dot'+(i===0?' on':'')+'\" data-i=\"'+i+'\" aria-label=\"Ir para banner '+(i+1)+'\"></button>';}).join(\"\")+'</div>';\n    var setas='<button class=\"b-arrow b-prev\" aria-label=\"Anterior\">‹</button><button class=\"b-arrow b-next\" aria-label=\"Próximo\">›</button>';\n    el.innerHTML=slides+setas+dots;\n\n    var reduz = !!(window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches);\n    var intervalo = Math.max(2000, (Number(D.banner_intervalo)||5)*1000);\n    var slidesEl=el.querySelectorAll(\".b-slide\"), dotsEl=el.querySelectorAll(\".b-dot\");\n    var atual=0, timer=null;\n    function mostrar(i){ atual=(i+bs.length)%bs.length; for(var j=0;j<slidesEl.length;j++) slidesEl[j].classList.toggle(\"on\",j===atual); for(var k=0;k<dotsEl.length;k++) dotsEl[k].classList.toggle(\"on\",k===atual); }\n    function proximo(){ mostrar(atual+1); }\n    function parar(){ if(timer){ clearInterval(timer); timer=null; } }\n    function iniciar(){ parar(); if(!reduz) timer=setInterval(proximo,intervalo); }\n    function reagendar(){ parar(); if(!reduz) setTimeout(iniciar, Math.max(intervalo, 6000)); }\n    var prev=el.querySelector(\".b-prev\"), next=el.querySelector(\".b-next\");\n    if(prev) prev.onclick=function(){ mostrar(atual-1); reagendar(); };\n    if(next) next.onclick=function(){ proximo(); reagendar(); };\n    for(var d=0; d<dotsEl.length; d++){ (function(btn){ btn.onclick=function(){ mostrar(Number(btn.getAttribute(\"data-i\"))||0); reagendar(); }; })(dotsEl[d]); }\n    // swipe no celular\n    var x0=null;\n    el.addEventListener(\"touchstart\", function(e){ x0=e.touches[0].clientX; parar(); }, {passive:true});\n    el.addEventListener(\"touchend\", function(e){ if(x0==null) return; var dx=e.changedTouches[0].clientX-x0; if(Math.abs(dx)>40){ if(dx<0) proximo(); else mostrar(atual-1); } x0=null; reagendar(); }, {passive:true});\n    // pausa ao interagir com o mouse (desktop)\n    el.addEventListener(\"mouseenter\", parar);\n    el.addEventListener(\"mouseleave\", iniciar);\n    iniciar();\n  }\n\n  // ---------- MODAL PRODUTO ----------\n  function corAtual(p){ if(sel.corId){ var c=(p.cores||[]).filter(function(x){return x.id_cor===sel.corId;})[0]; if(c) return c; } return (p.cores||[]).filter(function(x){return !x.oculta;})[0] || (p.cores||[])[0] || null; }\n  function qKey(cod,idt){ return sel.corId+\"|\"+cod+\"|\"+idt; }\n\n  function abrir(id){\n    var p=findProd(id); if(!p) return;\n    sel.prod=p; sel.qtd={};\n    var vis=coresVisiveis(p);\n    var c0=vis[0] || (p.cores||[]).filter(function(x){return !x.oculta;})[0] || (p.cores||[])[0];\n    sel.corId=c0?c0.id_cor:null;\n    renderDetalhe();\n    document.getElementById(\"modal\").classList.add(\"show\");\n    document.body.style.overflow=\"hidden\";\n  }\n  window.__fechar=function(){ document.getElementById(\"modal\").classList.remove(\"show\"); document.body.style.overflow=\"\"; };\n\n  function blocosHTML(p){\n    var b=p.blocos; if(!b||typeof b!==\"object\") return \"\";\n    return Object.keys(b).map(function(k){\n      var v=String(b[k]==null?\"\":b[k]).trim(); if(!v) return \"\";\n      var itens=v.split(\"\\n\").map(function(x){return x.trim();}).filter(Boolean).map(function(x){return \"<li>\"+esc(x)+\"</li>\";}).join(\"\");\n      return '<div class=\"bloco\"><h5>'+esc(k)+'</h5><ul>'+itens+'</ul></div>';\n    }).join(\"\");\n  }\n  // Cores como BOLINHAS com a textura real (a mesma foto cc.foto que já existe).\n  // Sem foto → cai na cor sólida (hex). Nome: no tooltip + destacado na área da cor.\n  function coresHTML(p){\n    // quantas peças já foram escolhidas em cada cor (pra marcar as bolinhas)\n    var porCor={};\n    Object.keys(sel.qtd).forEach(function(k){ var q=Number(sel.qtd[k])||0; if(q<=0) return; var corId=k.slice(0,k.indexOf(\"|\")); porCor[corId]=(porCor[corId]||0)+q; });\n    return coresVisiveis(p).map(function(c){\n      var cc=CORES[c.id_cor]||{}; var on=String(c.id_cor)===String(sel.corId)?\" on\":\"\";\n      var fundo=cc.foto? \"background-image:url('\"+esc(cc.foto)+\"')\" : 'background-color:'+esc(cc.hex||\"#ddd\");\n      var n=porCor[c.id_cor]||0; var badge=n>0?'<span class=\"sw-n\">'+n+'</span>':'';\n      return '<button type=\"button\" class=\"sw-dot'+on+(n>0?' has':'')+'\" data-cor=\"'+esc(c.id_cor)+'\" title=\"'+esc(cc.nome||\"\")+'\" aria-label=\"'+esc(cc.nome||\"\")+'\" style=\"'+fundo+'\">'+badge+'</button>';\n    }).join(\"\");\n  }\n  function corFotoHTML(p){\n    var cc=CORES[sel.corId]||{}; if(!cc.nome) return \"\";\n    var img=cc.foto? '<img class=\"cf-img\" src=\"'+esc(cc.foto)+'\" data-nome=\"'+esc(cc.nome||\"\")+'\" onclick=\"__zoomCor(this.src,this.getAttribute(\\'data-nome\\'))\" onerror=\"this.style.display=\\'none\\'\">' : '<div class=\"cf-img ph\"></div>';\n    return '<div class=\"corfoto\">'+img+'<div class=\"cf-d\"><div class=\"cf-nm\">'+esc(cc.nome)+'</div>'+(cc.foto?'<div class=\"cf-amp\">🔍 clique para ampliar</div>':'')+'</div></div>';\n  }\n  // Lightbox da foto do tecido da cor (abre a imagem grande pro cliente ver o detalhe).\n  window.__zoomCor=function(src,nome){\n    if(!src) return;\n    var ov=document.createElement(\"div\"); ov.className=\"lightbox\";\n    ov.innerHTML='<img src=\"'+src+'\" alt=\"\">'+(nome?'<div class=\"cap\">'+esc(nome)+'</div>':'')+'<button class=\"lb-x\" aria-label=\"fechar\">✕</button>';\n    document.body.appendChild(ov);\n    ov.addEventListener(\"click\",function(){ try{document.body.removeChild(ov);}catch(e){} });\n  };\n  // saldo da variação (produto+tamanho+cor selecionada), se o estoque por variação existir.\n  function estSaldo(cod,idt){\n    var med=medidaDe(idt); var m=EST[cod]&&EST[cod][med]; if(!m) return null;\n    var v=m[sel.corId]; return (v==null)?null:(Number(v)||0);\n  }\n  // saldo de uma COR específica (pra ocultar opção/cor sem estoque)\n  function estSaldoCor(cod,idt,corId){ var med=medidaDe(idt); var m=EST[cod]&&EST[cod][med]; if(!m) return null; var v=m[corId]; return (v==null)?null:(Number(v)||0); }\n  // só filtra se for pronta entrega/kit E houver dados de estoque (senão não esconde nada)\n  function filtraEstoque(p){ if(!(p.pronta_entrega||p._kit)) return false; var has=false; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){ if(EST[l.cod]) has=true; });}); return has; }\n  // a cor tem estoque em ALGUM tamanho?\n  function corComEstoque(p,corId){ var ok=false; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){ var s=estSaldoCor(l.cod,l.id_tamanho,corId); if(s!=null&&s>0) ok=true; });}); return ok; }\n  // cores a mostrar: oculta as sem estoque (pronta entrega/kit); nunca deixa a lista vazia\n  function coresVisiveis(p){ var cs=(p.cores||[]).filter(function(c){return !c.oculta;}); if(!filtraEstoque(p)) return cs; var cE=cs.filter(function(c){return corComEstoque(p,c.id_cor);}); return cE.length?cE:cs; }\n  // texto de estoque por linha, no estilo do catálogo: \"7 em estoque\" / \"últimas 2 unidades\".\n  function estTxtLinha(cod,idt){\n    var s=estSaldo(cod,idt); if(s==null) return \"\";\n    // Pronta entrega / kit: estoque 0 = ESGOTADO (não é feito sob encomenda).\n    var pe = sel.prod && (sel.prod.pronta_entrega || sel.prod._kit);\n    if(s<=0) return '<div class=\"estx off\">'+(pe?'estoque esgotado':'sob encomenda')+'</div>';\n    if(s<=3) return '<div class=\"estx low\">'+(s===1?'última unidade':'últimas '+s+' unidades')+'</div>';\n    return '<div class=\"estx\">'+s+' em estoque</div>';\n  }\n  function tamanhosHTML(p){\n    var cc=CORES[sel.corId]||{}; var filtra=filtraEstoque(p);\n    var grupos=(p.grupos||[]).map(function(g){\n      var rows=(g.linhas||[]).map(function(l){\n        // pronta entrega/kit: oculta a opção SEM estoque na cor selecionada\n        if(filtra){ var s=estSaldo(l.cod,l.id_tamanho); if(s!=null&&s<=0) return \"\"; }\n        var k=qKey(l.cod,l.id_tamanho); var q=sel.qtd[k]||0;\n        return '<div class=\"tamrow\"><div class=\"medbox\"><div class=\"med\">'+esc(medidaDe(l.id_tamanho).replace(/(\\d)\\s*[×xX]\\s*(\\d)/g,\"$1 × $2\"))+'</div>'+estTxtLinha(l.cod,l.id_tamanho)+'</div>'+\n          '<div class=\"pr\">'+brl(precoLinha(l))+'</div>'+\n          '<div class=\"stepper\" data-k=\"'+esc(k)+'\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"0\" value=\"'+q+'\"><button data-d=\"1\">+</button></div></div>';\n      }).join(\"\");\n      if(!rows) return \"\";                    // seção sem nenhuma opção visível → some\n      return '<div class=\"grp\"><div class=\"t\">'+esc(g.titulo||\"Itens\")+'</div>'+rows+'</div>';\n    }).join(\"\");\n    if(!grupos) grupos='<div class=\"estx off\" style=\"padding:10px 0\">Sem opções em estoque nesta cor.</div>';\n    return '<div class=\"lbl\">Escolha os tamanhos — <b>'+esc(cc.nome||\"\")+'</b></div>'+grupos;\n  }\n  function prazoHTML(p){\n    var est=estoqueProduto(p);\n    return '<div class=\"prazo\">'+(est>0? '📦 Em estoque — envio rápido.' : '🧶 Produção sob encomenda.')+'</div>';\n  }\n  // Mapa de todas as linhas do produto por \"cod|idtam\" (pra achar preço/medida a\n  // partir da chave de quantidade, que é \"corId|cod|idtam\").\n  function linhasDoProd(p){\n    var m={};\n    (p.grupos||[]).forEach(function(g){ (g.linhas||[]).forEach(function(l){ m[l.cod+\"|\"+l.id_tamanho]={l:l,g:g}; }); });\n    return m;\n  }\n  // Resumo do pedido (peças + valor) — soma TODAS as cores selecionadas (não só a\n  // cor que está aberta), pra a cliente ver o total real antes de adicionar.\n  function resumoHTML(p){\n    var pecas=0, total=0, LIN=linhasDoProd(p);\n    // o que está selecionando AGORA (ainda não adicionado)\n    Object.keys(sel.qtd).forEach(function(k){\n      var q=Number(sel.qtd[k])||0; if(q<=0) return;\n      var i=k.indexOf(\"|\"); var lk=k.slice(i+1);\n      var ref=LIN[lk]; if(!ref) return;\n      pecas+=q; total+=q*precoLinha(ref.l);\n    });\n    // o que JÁ está no carrinho DESTE modelo (não zera ao adicionar — só some ao fechar a compra)\n    var cp=0, ct=0;\n    (CART||[]).forEach(function(it){ if(it.pid===p.id){ cp+=Number(it.qtd)||0; ct+=(Number(it.qtd)||0)*(Number(it.preco)||0); } });\n    var tp=pecas+cp, tt=total+ct;\n    var nota = cp>0 ? '<span class=\"rz-c\">'+cp+' no carrinho</span>' : '';\n    return '<span class=\"rz-q\">'+tp+' '+(tp===1?'peça':'peças')+'</span>'+nota+'<b class=\"rz-v\">'+brl(tt)+'</b>';\n  }\n  function atualizarResumo(){ var el=document.getElementById(\"resumo\"); if(el) el.innerHTML=resumoHTML(sel.prod); }\n  function renderDetalhe(){\n    var p=sel.prod;\n    var foto = p.foto? '<div class=\"ph\">'+inicial(p.nome)+'</div><img src=\"'+esc(p.foto)+'\" onerror=\"this.remove()\">' : '<div class=\"ph\">'+inicial(p.nome)+'</div>';\n    var video = p.video? '<video class=\"vid\" controls preload=\"metadata\" src=\"'+esc(p.video)+'\"></video>' : '';\n    var linhaLb = p.pronta_entrega?\"Pronta Entrega\":(p._edicao_limitada?\"Edição Limitada\":(\"Linha \"+(p.linha||\"\").replace(/^\\w/,function(c){return c.toUpperCase();})));\n    var ncores=coresVisiveis(p).length;\n    document.getElementById(\"sheet\").innerHTML =\n      '<div class=\"topo\"><span class=\"lb\">'+esc(linhaLb)+'</span><button class=\"fechar\" onclick=\"__fechar()\">✕</button></div>'+\n      '<div class=\"det\">'+\n        '<div class=\"lado-foto\">'+foto+'</div>'+\n        '<div class=\"lado-info\">'+\n          '<div class=\"linhalb\">'+esc(linhaLb)+'</div>'+\n          '<h3 class=\"nome serif\">'+esc(p.nome)+'</h3>'+\n          video+\n          (p.composicao?'<div class=\"comp\">'+esc(p.composicao)+'</div>':'')+\n          blocosHTML(p)+\n          prazoHTML(p)+\n          '<div class=\"montar\"><h4>Montar pedido</h4>'+\n            '<div class=\"cor-sticky\">'+\n              '<div class=\"lbl\">Escolha a cor'+(ncores>1?' <span class=\"cnt\">· '+ncores+' cores disponíveis</span>':'')+'</div><div class=\"cores\" id=\"cores\">'+coresHTML(p)+'</div>'+\n              '<div id=\"corfoto\">'+corFotoHTML(p)+'</div>'+\n            '</div>'+\n            '<div id=\"tamanhos\">'+tamanhosHTML(p)+'</div>'+\n            '<div class=\"resumo\" id=\"resumo\">'+resumoHTML(p)+'</div>'+\n            '<button class=\"addcart\" id=\"addcart\">Adicionar ao carrinho</button>'+\n          '</div>'+\n        '</div>'+\n      '</div>';\n    ligarDetalhe();\n  }\n  function atualizarCorArea(){\n    document.getElementById(\"cores\").innerHTML=coresHTML(sel.prod);\n    document.getElementById(\"corfoto\").innerHTML=corFotoHTML(sel.prod);\n    document.getElementById(\"tamanhos\").innerHTML=tamanhosHTML(sel.prod);\n    ligarTamanhos();\n    atualizarResumo();\n  }\n  function ligarDetalhe(){\n    document.getElementById(\"cores\").onclick=function(e){ var c=e.target.closest(\".sw-dot\"); if(!c)return; sel.corId=c.getAttribute(\"data-cor\"); atualizarCorArea(); };\n    document.getElementById(\"addcart\").onclick=adicionarAoCarrinho;\n    ligarTamanhos();\n  }\n  function ligarTamanhos(){\n    var box=document.getElementById(\"tamanhos\");\n    box.querySelectorAll(\".stepper\").forEach(function(st){\n      var k=st.getAttribute(\"data-k\"); var inp=st.querySelector(\"input\");\n      st.querySelectorAll(\"button\").forEach(function(b){ b.onclick=function(){ var d=Number(b.getAttribute(\"data-d\")); var v=Math.max(0,(Number(inp.value)||0)+d); inp.value=v; sel.qtd[k]=v; atualizarResumo(); }; });\n      inp.oninput=function(){ sel.qtd[k]=Math.max(0,Number(inp.value)||0); atualizarResumo(); };\n    });\n  }\n  function adicionarAoCarrinho(){\n    var p=sel.prod, add=0, LIN=linhasDoProd(p);\n    // Percorre TODAS as cores selecionadas (a chave é \"corId|cod|idtam\") — não só a\n    // cor que está aberta —, pra todas as cores escolhidas entrarem no carrinho.\n    Object.keys(sel.qtd).forEach(function(k){\n      var q=Number(sel.qtd[k])||0; if(q<=0) return;\n      var i=k.indexOf(\"|\"); var corId=k.slice(0,i), lk=k.slice(i+1);\n      var ref=LIN[lk]; if(!ref) return;\n      var l=ref.l, g=ref.g, cc=CORES[corId]||{}, preco=precoLinha(l);\n      var achou=CART.filter(function(it){return it.cod===l.cod&&it.id_tamanho===l.id_tamanho&&String(it.corId)===String(corId)&&it.regiao===regiao;})[0];\n      if(achou){ achou.qtd+=q; } else {\n        CART.push({pid:p.id, nome:p.nome, grupo:g.titulo||\"\", cod:l.cod, id_tamanho:l.id_tamanho, medida:medidaDe(l.id_tamanho), corId:corId, corNome:cc.nome||\"\", preco:preco, regiao:regiao, qtd:q});\n      }\n      add+=q;\n    });\n    if(!add){ alert(\"Escolha a quantidade de pelo menos um tamanho.\"); return; }\n    sel.qtd={}; // zera a seleção de todas as cores\n    salvarCart(); atualizarCartN();\n    // feedback: zera os inputs e pergunta se continua no mesmo modelo ou escolhe outro\n    atualizarCorArea();\n    perguntarContinuar(add);\n  }\n  // Popup após adicionar: continuar neste modelo (fica no produto) ou escolher outro (volta ao catálogo).\n  function perguntarContinuar(add){\n    var ov=document.createElement(\"div\"); ov.className=\"popconf\";\n    ov.innerHTML=\n      '<div class=\"popconf-box\" role=\"dialog\" aria-modal=\"true\">'+\n        '<div class=\"popconf-ic\">🛒</div>'+\n        '<div class=\"popconf-tit\">'+add+' peça'+(add>1?'s':'')+' no carrinho!</div>'+\n        '<div class=\"popconf-sub\">Quer continuar neste modelo ou escolher outro?</div>'+\n        '<div class=\"popconf-acts\">'+\n          '<button class=\"popconf-b1\">Continuar neste modelo</button>'+\n          '<button class=\"popconf-b2\">Escolher outro modelo</button>'+\n        '</div>'+\n        '<button class=\"popconf-cart\">🛒 Ver meu carrinho</button>'+\n      '</div>';\n    document.body.appendChild(ov);\n    function fechar(){ try{ document.body.removeChild(ov); }catch(e){} }\n    ov.addEventListener(\"click\",function(e){ if(e.target===ov) fechar(); });\n    ov.querySelector(\".popconf-b1\").onclick=function(){ fechar(); };                         // segue no mesmo produto\n    ov.querySelector(\".popconf-b2\").onclick=function(){ fechar(); window.__fechar(); };        // fecha o produto → volta ao catálogo\n    ov.querySelector(\".popconf-cart\").onclick=function(){ fechar(); window.__fechar(); abrirCarrinho(); };\n  }\n\n  // ---------- CARRINHO ----------\n  function cnpjSalvo(){ try{ return localStorage.getItem(\"bt_cnpj\")||\"\"; }catch(e){ return \"\"; } }\n  function hashStr(s){ var h=5381,i=s.length; while(i){ h=(h*33)^s.charCodeAt(--i); } return (h>>>0).toString(36); }\n  function carregarCart(){ try{ return JSON.parse(localStorage.getItem(\"bt_carrinho\")||\"[]\")||[]; }catch(e){ return []; } }\n  function salvarCart(){ try{ localStorage.setItem(\"bt_carrinho\", JSON.stringify(CART)); }catch(e){} }\n  function cartQtd(){ return CART.reduce(function(s,i){return s+(Number(i.qtd)||0);},0); }\n  function cartTotal(){ return CART.reduce(function(s,i){return s+(Number(i.qtd)||0)*(Number(i.preco)||0);},0); }\n  function atualizarCartN(){ document.getElementById(\"cartN\").textContent=cartQtd(); }\n  function abrirCarrinho(){ renderCarrinho(); document.getElementById(\"cart\").classList.add(\"show\"); document.body.style.overflow=\"hidden\"; }\n  window.__fecharCart=function(){ document.getElementById(\"cart\").classList.remove(\"show\"); if(!document.getElementById(\"modal\").classList.contains(\"show\")) document.body.style.overflow=\"\"; };\n  function renderCarrinho(){\n    var itens = CART.length? CART.map(function(it,ix){\n      return '<div class=\"citem\"><div class=\"d\"><div class=\"nm\">'+esc(it.nome)+'</div>'+\n        '<div class=\"meta\">'+esc(it.grupo?it.grupo+\" · \":\"\")+esc(it.medida)+' · '+esc(it.corNome)+'</div>'+\n        '<div class=\"l2\"><div class=\"stepper\" data-ix=\"'+ix+'\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"1\" value=\"'+(Number(it.qtd)||0)+'\"><button data-d=\"1\">+</button></div>'+\n        '<span class=\"sub\">'+brl((Number(it.qtd)||0)*(Number(it.preco)||0))+'</span></div>'+\n        '<button class=\"rm\" data-rm=\"'+ix+'\">remover</button></div></div>';\n    }).join(\"\") : '<div class=\"cvazio\">Seu carrinho está vazio.<br>Escolha um produto e monte seu pedido.</div>';\n    document.getElementById(\"cartPane\").innerHTML=\n      '<div class=\"ctopo\"><h3 class=\"serif\">🛒 Meu carrinho</h3><button class=\"fechar\" onclick=\"__fecharCart()\">✕</button></div>'+\n      '<div class=\"itens\">'+itens+'</div>'+\n      '<div class=\"cfoot\"><div class=\"tot\"><span>Total</span><b>'+brl(cartTotal())+'</b></div>'+\n      (CART.length?('<label style=\"display:block;font-size:15px;color:#555;margin:2px 0 8px\">Informe o CNPJ da sua loja'+\n        '<input id=\"cnpjInp\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"00.000.000/0000-00\" value=\"'+esc(cnpjSalvo())+'\" style=\"display:block;width:100%;box-sizing:border-box;margin-top:4px;padding:12px;border:1px solid #d6d0c4;border-radius:10px;font-size:16px\"></label>'+\n        '<div id=\"cmsg\" style=\"font-size:13px;margin:0 0 8px;min-height:1px;line-height:1.35\"></div>'):'')+\n      '<button class=\"fin\" id=\"finalizar\"'+(CART.length?\"\":\" disabled\")+'>'+(CART.length?\"Finalizar pedido\":\"Finalizar pedido\")+'</button></div>';\n    var box=document.getElementById(\"cartPane\");\n    box.querySelectorAll(\".citem .stepper\").forEach(function(st){\n      var ix=Number(st.getAttribute(\"data-ix\")); var inp=st.querySelector(\"input\");\n      st.querySelectorAll(\"button\").forEach(function(b){ b.onclick=function(){ var d=Number(b.getAttribute(\"data-d\")); CART[ix].qtd=Math.max(1,(Number(CART[ix].qtd)||1)+d); salvarCart(); atualizarCartN(); renderCarrinho(); }; });\n      inp.onchange=function(){ CART[ix].qtd=Math.max(1,Number(inp.value)||1); salvarCart(); atualizarCartN(); renderCarrinho(); };\n    });\n    box.querySelectorAll(\"[data-rm]\").forEach(function(b){ b.onclick=function(){ CART.splice(Number(b.getAttribute(\"data-rm\")),1); salvarCart(); atualizarCartN(); renderCarrinho(); }; });\n    var fin=document.getElementById(\"finalizar\"); if(fin) fin.onclick=finalizarPedido;\n  }\n  function finalizarPedido(){\n    if(!CART.length) return;\n    var btn=document.getElementById(\"finalizar\"); var msg=document.getElementById(\"cmsg\");\n    var cnpjEl=document.getElementById(\"cnpjInp\"); var cnpj=(cnpjEl&&cnpjEl.value||\"\").trim();\n    var dig=cnpj.replace(/\\D+/g,\"\");\n    function erro(m){ if(msg){ msg.textContent=m; msg.style.color=\"#b91c1c\"; } }\n    if(dig.length<11){ erro(\"Digite o CNPJ (ou CPF) da sua loja para enviar o pedido.\"); if(cnpjEl) cnpjEl.focus(); return; }\n    try{ localStorage.setItem(\"bt_cnpj\", cnpj); }catch(e){}\n    var itens=CART.map(function(it){ return {cod:it.cod, medida:it.medida, corNome:it.corNome, corId:it.corId, qtd:it.qtd, preco:it.preco, regiao:it.regiao, nome:it.nome, grupo:it.grupo}; });\n    var idem=hashStr(dig+\"|\"+JSON.stringify(itens));\n    if(msg){ msg.textContent=\"\"; }\n    btn.disabled=true; btn.textContent=\"Enviando…\";\n    fetch(\"/api/loja/pedido\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({cnpj:cnpj, itens:itens, idem:idem})})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok, j:j||{}}; }); })\n      .then(function(res){\n        if(res.ok && res.j.ok){\n          CART=[]; salvarCart(); atualizarCartN();\n          var nome=res.j.cliente?(\", \"+esc(res.j.cliente)):\"\";\n          document.getElementById(\"cartPane\").innerHTML=\n            '<div class=\"ctopo\"><h3 class=\"serif\">🛒 Meu carrinho</h3><button class=\"fechar\" onclick=\"__fecharCart()\">✕</button></div>'+\n            '<div class=\"itens\"><div class=\"cvazio\" style=\"color:#166534;font-weight:600\">✓ '+esc(res.j.msg||\"Pedido enviado!\")+'</div>'+\n            '<div class=\"cvazio\" style=\"font-weight:400\">Obrigado'+nome+'! Qualquer dúvida, fale com a Big Tricot.</div></div>';\n        } else {\n          var m=res.j.msg||\"Não consegui enviar o pedido agora. Tente novamente.\";\n          if(res.j.detalhe&&res.j.detalhe.length){ m+=\" (\"+res.j.detalhe.join(\"; \")+\")\"; }\n          erro(m); btn.disabled=false; btn.textContent=\"Finalizar pedido\";\n        }\n      })\n      .catch(function(){ erro(\"Sem conexão no momento. Tente novamente.\"); btn.disabled=false; btn.textContent=\"Finalizar pedido\"; });\n  }\n\n  // ---------- eventos globais ----------\n  document.getElementById(\"app\").addEventListener(\"click\",function(e){ var el=e.target.closest(\".prod\"); if(el) abrir(el.getAttribute(\"data-id\")); });\n  document.getElementById(\"modal\").addEventListener(\"click\",function(e){ if(e.target.id===\"modal\") window.__fechar(); });\n  document.getElementById(\"cart\").addEventListener(\"click\",function(e){ if(e.target.id===\"cart\") window.__fecharCart(); });\n  document.getElementById(\"abrirCart\").addEventListener(\"click\",abrirCarrinho);\n  document.getElementById(\"q\").addEventListener(\"input\",function(){ filtroTxt=this.value; render(); });\n  document.getElementById(\"abas\").addEventListener(\"click\",function(e){ var a=e.target.closest(\"a\"); if(!a)return; var t=document.getElementById(a.getAttribute(\"data-sec\")); if(t)t.scrollIntoView({behavior:\"smooth\"}); });\n  document.getElementById(\"cats\").addEventListener(\"click\",function(e){ var b=e.target.closest(\"button[data-sec]\"); if(!b)return; var t=document.getElementById(b.getAttribute(\"data-sec\")); if(t)t.scrollIntoView({behavior:\"smooth\"}); });\n\n  try{ var r=document.getElementById(\"rodape\"); var n=PRODUTOS.length; var d=D.estoque&&D.estoque.atualizadoMs? new Date(D.estoque.atualizadoMs):new Date(); r.textContent=n+\" produtos · atualizado em \"+d.toLocaleDateString(\"pt-BR\"); }catch(e){}\n\n  // ---------- ENTRADA / SESSÃO DO CLIENTE (CNPJ) ----------\n  // A região de preço (Sul/Norte) vem do cadastro do cliente — o cliente NÃO escolhe.\n  function cliSalvo(){ try{ return JSON.parse(localStorage.getItem(\"bt_cli\")||\"null\"); }catch(e){ return null; } }\n  function mostrarSaudacao(nome){\n    var el=document.getElementById(\"saudacao\"); if(!el) return;\n    if(nome){ el.style.display=\"flex\"; el.innerHTML='Olá, <b style=\"color:#fff\">'+esc(nome)+'</b> · <a href=\"#\" id=\"sairLoja\" style=\"color:#e7a187;text-decoration:none\">trocar</a>';\n      var s=document.getElementById(\"sairLoja\"); if(s) s.onclick=function(ev){ ev.preventDefault(); sairLoja(); };\n    } else { el.style.display=\"none\"; el.innerHTML=\"\"; }\n  }\n  function aplicarSessao(nome,reg){\n    regiao = (reg===\"norte\")?\"norte\":\"sul\";\n    try{ localStorage.setItem(\"bt_cli\", JSON.stringify({nome:nome||\"\", regiao:regiao})); }catch(e){}\n    mostrarSaudacao(nome);\n    document.getElementById(\"entrada\").style.display=\"none\";\n    document.body.style.overflow=\"\";\n    render(); if(document.getElementById(\"modal\").classList.contains(\"show\")) renderDetalhe();\n  }\n  function abrirEntrada(){\n    var ov=document.getElementById(\"entrada\"); ov.style.display=\"flex\"; document.body.style.overflow=\"hidden\";\n    var inp=document.getElementById(\"entCnpj\"); if(inp && !inp.value) inp.value=cnpjSalvo();\n    setTimeout(function(){ try{ inp.focus(); }catch(e){} },50);\n  }\n  function sairLoja(){ try{ localStorage.removeItem(\"bt_cli\"); localStorage.removeItem(\"bt_cnpj\"); }catch(e){} mostrarSaudacao(\"\"); abrirEntrada(); }\n  function entrarLoja(){\n    var inp=document.getElementById(\"entCnpj\"); var msg=document.getElementById(\"entMsg\"); var btn=document.getElementById(\"entBtn\");\n    var cnpj=(inp&&inp.value||\"\").trim(); var dig=cnpj.replace(/\\D+/g,\"\");\n    if(dig.length<11){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite o CNPJ (ou CPF) da sua loja.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Entrando…\";\n    fetch(\"/api/loja/entrar\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({cnpj:cnpj})})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Entrar\";\n        if(res.ok && res.j.ok){ try{ localStorage.setItem(\"bt_cnpj\", cnpj); }catch(e){} aplicarSessao(res.j.nome, res.j.regiao); }\n        else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui validar o CNPJ. Tente novamente.\"; }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Entrar\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão no momento. Tente novamente.\"; });\n  }\n  document.getElementById(\"entBtn\").addEventListener(\"click\",entrarLoja);\n  document.getElementById(\"entCnpj\").addEventListener(\"keydown\",function(e){ if(e.key===\"Enter\") entrarLoja(); });\n\n  // Banner pode abrir um produto do catálogo ao clicar (chamado pelo onclick do banner).\n  window.__abrirProd=function(id){ try{ abrir(id); window.scrollTo({top:0,behavior:\"smooth\"}); }catch(e){} };\n  atualizarCartN();\n  renderBanner();\n  render();\n  ligarWhatsApp();\n\n  // Inicia sessão: usa o que já está salvo pra mostrar rápido, e revalida no servidor.\n  (function iniciarSessao(){\n    var c=cliSalvo(); if(c && c.regiao){ regiao=(c.regiao===\"norte\")?\"norte\":\"sul\"; mostrarSaudacao(c.nome); }\n    var dig=(cnpjSalvo()||\"\").replace(/\\D+/g,\"\");\n    if(dig.length>=11){\n      fetch(\"/api/loja/entrar\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({cnpj:cnpjSalvo()})})\n        .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n        .then(function(res){ if(res.ok && res.j.ok){ aplicarSessao(res.j.nome,res.j.regiao); } else { sairLoja(); } })\n        .catch(function(){ /* offline: segue com o que estava salvo */ });\n    } else { abrirEntrada(); }\n  })();\n})();\n</script>\n</body>\n</html>\n";
